try:
    if a > 1:
        pass
except ValueError as e:
    print("ValueError:", e)
try:
    bool(np.array([]))
except ValueError as e:
    print("ValueError:", e)
print(a.copy(), np.copy(a), a.T, a.dtype == np.int64, a.dtype == float, str(a.dtype), repr(a.dtype), np.array([1.0]).dtype == 'float64')

